import { createEffect, createSignal, For, on, onCleanup, onMount, Show, useContext } from "solid-js";

import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { CollapsibleContainer } from "#core/ui-next/components/collapsible-container.jsx";
import { Divider } from "#core/ui-next/components/divider.jsx";
import { Dropdown, DropdownItem } from "#core/ui-next/components/dropdown.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { HotkeyContext } from "#core/ui-next/services/hotkey.js";
import { useWindowSize } from "#core/ui-next/utilities/layout-utilities.js";
import { createLayoutComplete } from "#core/ui-next/utilities/solid-utilities.js";

import { TriumphFilterOptions, useLegaciesScreenContext } from "#base/ui-next/screens/legacies/legacies-model.js";
import { TriumphCard } from "#base/ui-next/screens/legacies/triumph-card.jsx";

export const LegaciesTriumphTab = () => {
	const model = useLegaciesScreenContext();
	const hotkeyContext = useContext(HotkeyContext);
	const audio = useAudio("LegaciesTriumphsPopup");
	let root: HTMLDivElement | undefined;
	const layoutComplete = createLayoutComplete();
	const windowSize = useWindowSize();
	const [triumphCardHeight, setTriumphCardHeight] = createSignal<string | undefined>(undefined);
	const [hasInitialCardHeight, setHasInitialCardHeight] = createSignal(false);
	const [needsTriumphCardHeightUpdate, setNeedsTriumphCardHeightUpdate] = createSignal(false);

	//Make sure all triumph cards are the same height since some can grow to accomodate long descritions.
	const calculateTriumphCardHeights = () => {
		if (!root) {
			return;
		}

		const cards = Array.from(root.querySelectorAll<HTMLElement>(".triumph-card"));
		if (cards.length === 0) {
			setTriumphCardHeight(undefined);
			setHasInitialCardHeight(true);
			return;
		}

		const tallestCardHeight = Math.max(...cards.map((card) => Math.max(card.offsetHeight, card.scrollHeight)));
		const newHeight = tallestCardHeight + "px";
		setTriumphCardHeight(newHeight);
		setHasInitialCardHeight(true);
	};

	const matchesTriumphFilter = (filterOptions: string[], isTracked: boolean) => {
		const selectedFilter = model.selectedTriumphFilter();

		if (selectedFilter === TriumphFilterOptions.TRACKED) {
			return isTracked;
		}

		if (selectedFilter === TriumphFilterOptions.UNTRACKED) {
			return !isTracked;
		}

		return filterOptions.some((filter) => filter == selectedFilter);
	};

	onMount(() => {
		audio("popup-open");
		hotkeyContext.registerNavtray("accept", "LOC_LEGACIES_TRACK_UNTRACK");
		hotkeyContext.registerNavtray("shell-action-2", "LOC_ADVANCED_START_FILTER");

		createEffect(
			on([layoutComplete, model.selectedTriumphFilter, windowSize], () => {
				if (layoutComplete() && !needsTriumphCardHeightUpdate()) {
					setNeedsTriumphCardHeightUpdate(true);
					delayByFrame(() => {
						calculateTriumphCardHeights();
						setNeedsTriumphCardHeightUpdate(false);
					});
				}
			}),
		);
	});

	onCleanup(() => {
		hotkeyContext.unregisterNavtray("accept");
		hotkeyContext.unregisterNavtray("shell-action-2");
	});

	const currentSetType = Configuration.getGame().getValue("LegacySet");
	const currentSetDefinition = GameInfo.LegacySets.find((set) => set.$hash === currentSetType);

	const isDefaultOrNone =
		!currentSetDefinition ||
		currentSetDefinition.LegacySetType === "LEGACY_SET_DEFAULT" ||
		currentSetDefinition.LegacySetType === "LEGACY_SET_NONE";

	const triumphsTitle = Locale.compose("LOC_LEGACIES_TRIUMPHS_TITLE");
	const currentSetName = isDefaultOrNone
		? triumphsTitle
		: Locale.compose(currentSetDefinition!.Name) + " " + triumphsTitle;
	return (
		<>
			<div class="w-full text-center text-accent-2 text-sm">
				<L10n.Compose text="LOC_TRIUMPHS_TAB_DESCRIPTION" />
			</div>
			<div
				ref={root}
				class="mt-2 flex flex-col flex-auto items-center mx-8 mb-5 pl-8 pr-8 pt-2 relative"
				style={{
					"background-image":
						"linear-gradient(rgba(20, 20, 20, 0.8), rgba(20, 20, 20, 0.7), rgba(20, 20, 20, 0.8))",
				}}
			>
				<div
					class="absolute h-6 -top-0\.5 -left-1\.5 -right-1\.5"
					style={{
						"border-image-source": "url(blp:hud_section-line)",
						"border-image-slice": "4 32 0 32 fill",
						"border-image-width": "auto",
					}}
				/>
				<div class="flex flex-col flex-auto w-full pb-4 relative">
					<div class="flex flex-row w-full items-center px-4">
						<div class="text-secondary uppercase font-title">{currentSetName}</div>
						<div class="flex flex-row flex-auto items-center justify-end">
							<L10n.Compose text="LOC_ADVANCED_START_FILTER" />
							<Dropdown
								disableFocus={true}
								class="ml-2 w-60 pointer-events-auto grow-0"
								selectedItemTemplate={(item) => (
									<div
										class={`flex font-fit-shrink ${window.innerWidth <= Layout.pixelsToScreenPixels(1280) ? "text-xs" : ""}`}
									>
										<L10n.Stylize text={`LOC_LEGACIES_FILTER_${item}`} />
									</div>
								)}
								defaultValue={TriumphFilterOptions.DEFAULT}
								onItemSelected={(item) => {
									model.setSelectedTriumphFilter(item);
								}}
								hotkey="shell-action-2"
							>
								<For each={Object.keys(TriumphFilterOptions)}>
									{(item) => (
										<DropdownItem value={item}>
											<L10n.Stylize text={`LOC_LEGACIES_FILTER_${item}`} />
										</DropdownItem>
									)}
								</For>
							</Dropdown>
						</div>
					</div>
					<Divider.Horizontal class="w-full h-0\\.5 my-2" />
					<SpatialSlot
						name="TriumphsTabScrollable"
						class="flex-auto"
					>
						<ScrollArea class="flex-auto pl-4">
							<For each={model.triumphSections}>
								{(section) => (
									<CollapsibleContainer
										disableFocus={true}
										titleText={section.titleText}
										centerTitle={true}
										class="mb-2"
									>
										<div class="flex flex-row flex-wrap relative items-start justify-center pt-3">
											<For each={section.triumphs}>
												{(legacy) => (
													<Show
														when={matchesTriumphFilter(
															legacy.filterOptions,
															legacy.isTracked,
														)}
													>
														<TriumphCard
															triumph={legacy}
															model={model}
															style={{ height: triumphCardHeight() }}
															class={`${hasInitialCardHeight() && !needsTriumphCardHeightUpdate() ? "opacity-100" : "opacity-0"}`}
														/>
													</Show>
												)}
											</For>
										</div>
									</CollapsibleContainer>
								)}
							</For>
						</ScrollArea>
					</SpatialSlot>
				</div>
				<div
					class="absolute h-6 -bottom-0\.5 -left-1\.5 -right-1\.5 -scale-y-100"
					style={{
						"border-image-source": "url(blp:hud_section-line)",
						"border-image-slice": "4 32 0 32 fill",
						"border-image-width": "auto",
					}}
				/>
			</div>
		</>
	);
};
